package com.gameaggregator.publisherservice.application;import com.gameaggregator.platform.core.common.exception.NotFoundException;import com.gameaggregator.publisherservice.api.PublisherDtos.*;import com.gameaggregator.publisherservice.domain.*;import com.gameaggregator.publisherservice.infrastructure.*;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;@Service @Transactional public class PublisherService{final PublisherRepository publishers;final PublisherTeamMemberRepository team;final DistributionRightRepository rights;public PublisherService(PublisherRepository p,PublisherTeamMemberRepository t,DistributionRightRepository r){publishers=p;team=t;rights=r;}public Publisher create(Create r){var p=publishers.save(new Publisher(r.tenantId(),r.slug(),r.name(),r.ownerUserId()));team.save(new PublisherTeamMember(p.id,r.ownerUserId(),"OWNER"));return p;}public List<Publisher> list(){return publishers.findAll();}public Publisher get(UUID id){return publishers.findById(id).orElseThrow(()->new NotFoundException("PUBLISHER_NOT_FOUND","Publisher was not found"));}public Publisher update(UUID id,Update r){var p=get(id);p.name=r.name();return p;}public void delete(UUID id){publishers.delete(get(id));}public PublisherTeamMember team(UUID id,Team r){get(id);return team.save(new PublisherTeamMember(id,r.userId(),r.role()));}public DistributionRight right(UUID id,Right r){get(id);return rights.save(new DistributionRight(id,r.gameId(),r.territory(),r.startsOn(),r.endsOn()));}public List<DistributionRight> rights(UUID id){get(id);return rights.findAllByPublisherId(id);}}
